import json

with open('batches/batch_0018.json', encoding='utf-8') as f:
    data = json.load(f)

def try_fix_trim(s, encs):
    for cut in range(0, 6):
        t = s if cut == 0 else s[:-cut]
        for enc_from, enc_to in encs:
            try:
                return t.encode(enc_from).decode(enc_to), cut
            except Exception:
                continue
    return None, None

targets = {905: [('latin1','utf-8')], 929: [('latin1','shift_jis'),('latin1','utf-8')]}
for item in data:
    if item['idx'] in targets:
        print('=== idx', item['idx'], item['name'], '===')
        r, cut = try_fix_trim(item['body'], targets[item['idx']])
        if r:
            print(f'(trimmed {cut} chars)')
            print(r[:1400])
        else:
            print('still failing')
        print()
